344:         private List<VmProcedure> GetCurrentSolProcedureList()
345:         {
346:             List<VmProcedure> procedureList = new List<VmProcedure>();
347:             string processName = string.Empty;
348:             var processInfoList = VmSolution.Instance.GetAllProcedureList();
349:             for (int i = 0; i < processInfoList.nNum; i++)
350:             {
351:                 processName = processInfoList.astProcessInfo[i].strProcessName;
352:                 procedureList.Add((VmProcedure)VmSolution.Instance[processName]);
353:             }
354: 
355:             return procedureList;
