382:         private void VmProcedure_OnWorkEndStatusCallBack(object sender, EventArgs e)
383:         {
384:             try
385:             {
386:                 VmProcedure procedure = sender as VmProcedure;
387:                 if (procedure != null)
388:                 {
389:                     var outputList = procedure.ModuResult.GetAllOutputNameInfo();
390:                     bool outputConfigIsWrong = true;
391:                     foreach (var ioNameInfo in outputList)
392:                     {
393:                         if (ioNameInfo.Name == "out" &&
394:                             ioNameInfo.TypeName == IMVS_MODULE_BASE_DATA_TYPE.IMVS_GRAP_TYPE_STRING)
395:                         {
396:                             var result = procedure.ModuResult.GetOutputString(ioNameInfo.Name);
397:                             string resultStrValue = result.astStringVal[0].strValue;
398:                             this.AppendLog("Result: " + resultStrValue);
399: 
400:                             // UpdateResultListBox("Result: " + resultStrValue);
401:                             // UpdateLableState(resultStrValue);
402:                             outputConfigIsWrong = false;
403:                         }
404:                     }
405:                     if (outputConfigIsWrong)
406:                     {
407:                         this.AppendLog("The result argument (out) is not exit or is not string format！");
408:                     }
409:                     this.AppendLog("Time" + procedure.ProcessTime);
410:                 }
411:             }
412:             catch (Exception ex)
413:             {
414:                 this.AppendLog(ex.Message);
415:             }

