837:         private void CalcuSubMapP1P2(PointF basePoint1, PointF basePoint2, PointF markP1, PointF markP2, out HTuple homat2dTrans)
838:         {
839:             double oldX1 = basePoint1.X;
840:             double oldY1 = basePoint1.Y;
841:             double oldX2 = basePoint2.X;
842:             double oldY2 = basePoint2.Y;
843:             double newX1 = markP1.X;
844:             double newY1 = markP1.Y;
845:             double newX2 = markP2.X;
846:             double newY2 = markP2.Y;
847: 
848:             HTuple oldAngle, newAngle;
849: 
850:             HOperatorSet.AngleLx(oldX1, oldY1, oldX2, oldY2, out oldAngle);
851:             HOperatorSet.AngleLx(newX1, newY1, newX2, newY2, out newAngle);
852: 
853:             HTuple oldX = (oldX1 + oldX2) / 2;
854:             HTuple oldY = (oldY1 + oldY2) / 2;
855:             HTuple newX = (newX1 + newX2) / 2;
856:             HTuple newY = (newY1 + newY2) / 2;
857: 
858:             HOperatorSet.VectorAngleToRigid(oldX, oldY, oldAngle, newX, newY, newAngle, out homat2dTrans);
859:            
860:             HOperatorSet.AffineTransPoint2d(homat2dTrans,1224,1024, out HTuple qx, out HTuple qy);
861:         }

