256:         /// <summary>
257:         /// 计算P1P2中点坐标及角度
258:         /// </summary>
259:         /// <param name="x1">x1</param>
260:         /// <param name="y1">y1</param>
261:         /// <param name="x2">x2</param>
262:         /// <param name="y2">y2</param>
263:         /// <returns>x,y,angle</returns>
264:         public (double, double, double) CalculateMidpoint(double x1, double y1, double x2, double y2)
265:         {
266:             double midX = (x1 + x2) / 2.0;
267:             double midY = (y1 + y2) / 2.0;
268: 
269:             // 计算两点之间的角度（弧度）
270:             double angleRad = Math.Atan2(y2 - y1, x2 - x1);
271: 
272:             // 将弧度转换为角度
273:             double angleDegrees = angleRad * (180.0 / Math.PI);
274: 
275:             return (midX, midY, angleDegrees);
276:         }
277: 
278:         /// <summary>
279:         /// 计算多点线性回归线角度
280:         /// </summary>
281:         /// <param name="points">点集</param>
282:         /// <returns>角度</returns>
283:         public double CalciLinearRegressionAngle(List<PointF> points)
284:         {
285:             double sumX = points.Sum(point => point.X);
286:             double sumY = points.Sum(point => point.Y);
287:             double sumXY = points.Sum(point => point.X * point.Y);
288:             double sumX2 = points.Sum(point => point.X * point.X);
289: 
290:             int n = points.Count;
291: 
292:             double slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
293:             double angleRad = Math.Atan(slope);
294:             double angleDegrees = angleRad * (180 / Math.PI);
295: 
296:             return angleDegrees;
297:         }
