600:         public static PointF Rotate(PointF point, PointF center, double angle)
601:         {
602:             // 将角度转换为弧度
603:             double angleInRadians = angle * (Math.PI / 180);
604: 
605:             // 计算相对于旋转中心的原始坐标
606:             double dx = point.X - center.X;
607:             double dy = point.Y - center.Y;
608: 
609:             // 计算旋转后的坐标
610:             float rotatedX = (float)(center.X + (dx * Math.Cos(angleInRadians)) - (dy * Math.Sin(angleInRadians)));
611:             float rotatedY = (float)(center.Y + (dx * Math.Sin(angleInRadians)) + (dy * Math.Cos(angleInRadians)));
612: 
613:             // 将旋转后的坐标返回
614:             return new PointF(rotatedX, rotatedY);
615:         }
616:         #endregion
617: 
618:         /// <summary>
619:         /// 根据偏移量及角度计算旋转后偏移量
620:         /// </summary>
621:         /// <param name="offsetX">x偏移</param>
622:         /// <param name="offsetY">y偏移</param>
623:         /// <param name="rotationAngle">旋转角度</param>
624:         /// <returns>偏移</returns>
625:         public PointF CalculateRotatedOffset(double offsetX, double offsetY, double rotationAngle)
626:         {
627:             // 将角度转换为弧度
628:             double rotationAngleInRadians = rotationAngle * Math.PI / 180.0f;
629: 
630:             // 计算旋转后的偏移量
631:             double rotatedOffsetX = offsetX * Math.Cos(rotationAngleInRadians) - offsetY * Math.Sin(rotationAngleInRadians);
632:             double rotatedOffsetY = offsetX * Math.Sin(rotationAngleInRadians) + offsetY * Math.Cos(rotationAngleInRadians);
633: 
634:             // 返回旋转后的偏移量
635:             return new PointF((float)rotatedOffsetX, (float)rotatedOffsetY);
636:         }

